ct_identity ON public.xpert_project_pipeline_round USING btree (id, \"projectId\")","valid":true},{"table":"xpert_project_pipeline_run","name":"IDX_cb786ce2a4f45277e357b4f868","definition":"CREATE INDEX \"IDX_cb786ce2a4f45277e357b4f868\" ON public.xpert_project_pipeline_run USING btree (\"organizationId\")","valid":true},{"table":"xpert_project_pipeline_run","name":"IDX_f32d948b6adb08c6082630df7b","definition":"CREATE INDEX \"IDX_f32d948b6adb08c6082630df7b\" ON public.xpert_project_pipeline_run USING btree (\"tenantId\")","valid":true},{"table":"xpert_project_pipeline_run","name":"pipeline_one_active_run","definition":"CREATE UNIQUE INDEX pipeline_one_active_run ON public.xpert_project_pipeline_run USING btree (\"instanceId\") WHERE (((state)::text = ANY ((ARRAY['pending'::character varying, 'active'::character varying, 'waiting'::character varying, 'cancelling'::character varying])::text[])) AND (\"deletedAt\" IS NULL))","valid":true,"alternatives":["CREATE UNIQUE INDEX pipeline_one_active_run ON public.xpert_project_pipeline_run USING btree (\"instanceId\") WHERE (((state)::text = ANY (ARRAY[('pending'::character varying)::text, ('active'::character varying)::text, ('waiting'::character varying)::text, ('cancelling'::character varying)::text])) AND (\"deletedAt\" IS NULL))"]},{"table":"xpert_project_pipeline_run","name":"pipeline_run_project_identity","definition":"CREATE UNIQUE INDEX pipeline_run_project_identity ON public.xpert_project_pipeline_run USING btree (id, \"projectId\")","valid":true},{"table":"xpert_project_task","name":"pipeline_task_instance","definition":"CREATE INDEX pipeline_task_instance ON public.xpert_project_task USING btree (\"projectId\", \"pipelineInstanceId\")","valid":true},{"table":"xpert_project_task","name":"pipeline_task_project_identity","definition":"CREATE UNIQUE INDEX pipeline_task_project_identity ON public.xpert_project_task USING btree (id, \"projectId\")","valid":true},{"table":"xpert_project_task","name":"project_task_provider_source","definition":"CREATE UNIQUE INDEX project_task_provider_source ON public.xpert_project_task USING btree (\"projectId\", \"providerKey\", \"sourceKey\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_fc87c42b119a6ae0eeaaf095fb","definition":"CREATE INDEX \"IDX_fc87c42b119a6ae0eeaaf095fb\" ON public.xpert_project_task_execution USING btree (\"tenantId\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_project_task_execution_dispatch","definition":"CREATE UNIQUE INDEX \"IDX_project_task_execution_dispatch\" ON public.xpert_project_task_execution USING btree (\"projectId\", \"createdById\", \"dispatchRequestId\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_project_task_execution_invocation","definition":"CREATE UNIQUE INDEX \"IDX_project_task_execution_invocation\" ON public.xpert_project_task_execution USING btree (\"invocationId\")","valid":true},{"table":"xpert_project_task_execution","name":"IDX_task_dispatch_due","definition":"CREATE INDEX \"IDX_task_dispatch_due\" ON public.xpert_project_task_execution USING btree (\"dispatchState\", \"dispatchNextAttemptAt\")","valid":true},{"table":"xpert_project_task_execution","name":"project_task_execution_source","definition":"CREATE UNIQUE INDEX project_task_execution_source ON public.xpert_project_task_execution USING btree (\"taskId\", \"sourceKey\")","valid":true},{"table":"xpert_task_execution","name":"IDX_e19800cc46fbbe4f7c7744a5d3","definition":"CREATE INDEX \"IDX_e19800cc46fbbe4f7c7744a5d3\" ON public.xpert_task_execution USING btree (status, \"leaseExpiresAt\")","valid":true},{"table":"xpert_task_execution","name":"uq_xpert_task_execution_occurrence","definition":"CREATE UNIQUE INDEX uq_xpert_task_execution_occurrence ON public.xpert_task_execution USING btree (\"taskId\", \"occurrenceKey\")","valid":true}]}$catalog$::jsonb AS catalog),
columns AS (
  SELECT c.relname AS "table", a.attname AS name, format_type(a.atttypid,a.atttypmod) AS type,
    a.attnotnull AS "notNull", pg_get_expr(d.adbin,d.adrelid) AS "default"
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
  WHERE n.nspname=current_schema() AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped
),
constraints AS (
  SELECT t.relname AS "table", c.conname AS name, pg_get_constraintdef(c.oid) AS definition,
    c.convalidated AS validated FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
),
indexes AS (
  SELECT t.relname AS "table", c.relname AS name, pg_get_indexdef(i.indexrelid) AS definition, i.indisvalid AS valid
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid
  JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=current_schema()
)
SELECT 'column:'||e."table"||'.'||e.name AS missing FROM expected,
  jsonb_to_recordset(catalog->'columns') AS e("table" text,name text,type text,"notNull" boolean,"default" text)
WHERE NOT EXISTS (SELECT 1 FROM columns a WHERE a."table"=e."table" AND a.name=e.name AND a.type=e.type
  AND a."notNull"=e."notNull" AND a."default" IS NOT DISTINCT FROM e."default")
UNION ALL
SELECT 'constraint:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'constraints') AS e("table" text,name text,definition text,validated boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM constraints a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.validated=e.validated)
UNION ALL
SELECT 'index:'||e."table"||'.'||e.name FROM expected,
  jsonb_to_recordset(catalog->'indexes') AS e("table" text,name text,definition text,valid boolean,alternatives text[])
WHERE NOT EXISTS (SELECT 1 FROM indexes a WHERE a."table"=e."table" AND a.name=e.name
  AND (a.definition=e.definition OR a.definition=ANY(e.alternatives)) AND a.valid=e.valid);
